// Shared simulation business metadata. The two new borrowing plans are
// manager-entered actions, never resources generated by the planner.
const DEMO_UNIT_YUAN = 1000000;
export const EXCHANGE_REPO_UNIT_YUAN = 1000;
export const EXCHANGE_REPO_MAX_ORDER_YUAN = 10000000000;
export const EXCHANGE_REPO_TENORS = Object.freeze([1,2,3,4,7,14,28,91,182]);

export const BUSINESS_TYPES = Object.freeze({
  reverse_repo: Object.freeze({ label:'逆回购', direction:'outflow', cashEffect:'outflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:null, needsPledge:false, needsQuota:false }),
  interbank_repo_financing: Object.freeze({ label:'正回购', direction:'inflow', cashEffect:'conditional_inflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:'cash_available', needsPledge:true, needsQuota:true }),
  exchange_repo_financing: Object.freeze({ label:'交易所融资（正回购）', direction:'inflow', cashEffect:'conditional_inflow',
    unitYuan:EXCHANGE_REPO_UNIT_YUAN, unitSource:'exchange_rule', creditKind:'cash_available', needsPledge:true, needsQuota:true,
    maxPerOrderYuan:EXCHANGE_REPO_MAX_ORDER_YUAN }),
  exchange_repo_lending: Object.freeze({ label:'交易所融券（逆回购）', direction:'outflow', cashEffect:'outflow',
    unitYuan:EXCHANGE_REPO_UNIT_YUAN, unitSource:'exchange_rule', creditKind:null, needsPledge:false, needsQuota:false,
    maxPerOrderYuan:EXCHANGE_REPO_MAX_ORDER_YUAN }),
  deposit: Object.freeze({ label:'银行存款', direction:'outflow', cashEffect:'outflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:null, needsPledge:false, needsQuota:false }),
  cd_buy: Object.freeze({ label:'存单买入', direction:'outflow', cashEffect:'outflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:null, needsPledge:false, needsQuota:false }),
  cd_sell: Object.freeze({ label:'存单卖出', direction:'inflow', cashEffect:'conditional_inflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:'cash_available', needsPledge:false, needsQuota:false,
    needsHolding:true }),
  bond_buy: Object.freeze({ label:'其他现券买入', direction:'outflow', cashEffect:'outflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:null, needsPledge:false, needsQuota:false }),
  bond_sell: Object.freeze({ label:'其他现券卖出', direction:'inflow', cashEffect:'conditional_inflow',
    unitYuan:DEMO_UNIT_YUAN, unitSource:'demo', creditKind:'cash_available', needsPledge:false, needsQuota:false,
    needsHolding:true }),
});

export const BUSINESS_DIRECTIONS = Object.freeze(Object.fromEntries(
  Object.entries(BUSINESS_TYPES).map(([key,meta]) => [key,meta.direction])));
export const isFinancing = type => type === 'interbank_repo_financing' || type === 'exchange_repo_financing';
export const isExchangeRepo = type => type === 'exchange_repo_financing' || type === 'exchange_repo_lending';
export const isSecuritySale = type => type === 'cd_sell' || type === 'bond_sell';
// Deposits are single tickets. Historical fills remain facts; any remaining
// amount must be arranged, filled or cancelled in one operation.
export const isIndivisible = type => type === 'deposit';
export function indivisibleAmountIssue(plan, balance, amountYuan) {
  if (!isIndivisible(plan?.businessType)) return null;
  if (!balance || balance.lockedYuan > 0)
    return '存款不可拆分：已有未成交占用，须先完成或整笔撤销原指令，再安排剩余存款';
  const required = plan.targetYuan - balance.filledYuan;
  return amountYuan === required ? null :
    `存款不可拆分：本笔剩余${required}元须全部安排或都不安排，本次${amountYuan}元`;
}
export function unitFor(type) {
  const unit = BUSINESS_TYPES[type]?.unitYuan;
  if (!unit) throw new Error('未知业务类型');
  return unit;
}

const clockSeconds = value => {
  if (typeof value !== 'string' || !/^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(value)) return null;
  const [h,m,s] = value.split(':').map(Number);
  return h * 3600 + m * 60 + s;
};
const between = (second,from,to) => second >= clockSeconds(from) && second <= clockSeconds(to);
export function windowStatus(clock, { mode, at } = {}) {
  if (mode !== 'send' && mode !== 'fill') throw new Error('窗口模式须为send或fill');
  if (!clock || clock.timezone !== 'Asia/Shanghai' || typeof clock.isTradingDay !== 'boolean' ||
      (mode === 'fill' && at == null)) return { result:'missing', reason:'交易日、交易所时区或成交时间缺失' };
  if (!clock.isTradingDay) return { result:'closed', reason:'非交易日' };
  const time = at ?? clock.time;
  const second = clockSeconds(time);
  if (second === null) return { result:'missing', reason:'时点缺失或格式无效' };
  const inAuction = between(second,'09:15:00','09:24:59');
  const atMatch = second === clockSeconds('09:25:00');
  const morning = between(second,'09:30:00','11:30:00');
  const afternoon = between(second,'13:00:00','15:30:00');
  if (mode === 'send' && inAuction) return { result:'open', session:'opening_auction', reason:'开盘集合申报时段' };
  if (mode === 'fill' && atMatch) return { result:'open', session:'opening_match', reason:'开盘集合成交时点' };
  if (morning || (afternoon && (mode === 'fill' || second < clockSeconds('15:30:00'))))
    return { result:'open', session:'continuous', reason:'连续竞价时段' };
  return { result:'closed', reason:'不在交易所回购新申报或成交时段' };
}

export function cancellationStatus(clock, { at } = {}) {
  const gate = windowStatus(clock,{mode:'send',at});
  if (gate.result !== 'open') return gate;
  const second = clockSeconds(at ?? clock.time);
  if (between(second,'09:20:00','09:25:00')) return { result:'closed', reason:'开盘集合竞价不可撤单时段' };
  return gate;
}
